package com.shopsphere.model;
public class User { private int userId; private String name,email,password,mobile,role; public int getUserId(){return userId;} public void setUserId(int x){userId=x;} public String getName(){return name;} public void setName(String x){name=x;} public String getEmail(){return email;} public void setEmail(String x){email=x;} public String getPassword(){return password;} public void setPassword(String x){password=x;} public String getMobile(){return mobile;} public void setMobile(String x){mobile=x;} public String getRole(){return role;} public void setRole(String x){role=x;} }
